module TopModule (
    input  wire [7:0] a,
    input  wire [7:0] b,
    output wire [7:0] s,
    output wire       overflow
);

    wire [7:0] sum;
    wire       overflow_flag;

    assign sum = a + b;

    // Compute overflow for signed addition
    assign overflow_flag = (a[7] & b[7] & (~sum[7])) | 
                          (~a[7] & ~b[7] & sum[7]);

    assign s = sum;
    assign overflow = overflow_flag;

endmodule

// Truth Table for TopModule:
// Inputs: a[7:0], b[7:0]
// Outputs: s[7:0], overflow
//
// Overflow occurs when adding two signed 8-bit numbers results in a value that
// cannot be represented in 8 bits (i.e., when the sign bit changes from the
// input operands to the result).
//
// Overflow conditions:
// 1. Both a and b are positive (a[7] = 0, b[7] = 0), and the result is negative (s[7] = 1)
// 2. Both a and b are negative (a[7] = 1, b[7] = 1), and the result is positive (s[7] = 0)

module TopModule (
    input  wire [7:0] a,
    input  wire [7:0] b,
    output wire [7:0] s,
    output wire       overflow
);

    wire [8:0] sum;
    assign sum = a + b;

    assign s = sum[7:0];
    assign overflow = (a[7] & b[7] & ~sum[7]) | (~a[7] & ~b[7] & sum[7]);

endmodule

