    // out_sop = (a'b'c'd) + (a'bc'd') + (a'bcd') + (ab'c'd) + (ab'cd') + (abc'd') + (abcd)
    // Simplified SOP: out_sop = (a'c'd) + (b'c'd') + (b'cd) + (acd') + (bcd')

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos = (a + b + c + d') * (a + b' + c' + d) * (a' + b + c' + d') * (a' + b' + c + d)

    // SOP implementation
    assign out_sop = 
        (a == 0 && c == 0 && d == 1) || 
        (a == 0 && b == 0 && c == 1 && d == 0) || 
        (a == 0 && b == 1 && c == 1 && d == 0) || 
        (a == 1 && b == 0 && c == 0 && d == 1) || 
        (a == 1 && b == 0 && c == 1 && d == 0) || 
        (a == 1 && b == 1 && c == 0 && d == 0) || 
        (a == 1 && b == 1 && c == 1 && d == 1);

    // POS implementation
    assign out_pos = 
        (a | b | c | (~d)) && 
        (a | (~b) | (~c) | d) && 
        ((~a) | b | (~c) | d) && 
        ((~a) | (~b) | c | d);

endmodule

module TopModule (
