    assign out_pos = 
        (a | (!b | !c | !d)) &  // excludes 0, 1, 4, 5, 6
        (a | (!b | c | !d)) &   // excludes 0, 1, 4, 5, 6
        (a | (!b | c | d)) &    // excludes 0, 1, 4, 5, 6
