    // out_sop is 1 for input values 2, 7, 15
    // Binary representations:
    // 2: 0010 -> a=0, b=0, c=1, d=0
    // 7: 0111 -> a=0, b=1, c=1, d=1
    // 15: 1111 -> a=1, b=1, c=1, d=1

    // SOP expression: (a' b' c d') + (a' b c d) + (a b c d)
    assign out_sop = (!a & !b & c & !d) | (!a & b & c & d) | (a & b & c & d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 1 when 2, 7, or 15 appear on the inputs
    // So, out_pos is 0 for the values 0, 1, 4, 5, 6, 9, 10, 13, 14

    // The complement of the SOP expression for out_sop is the POS expression for out_pos
    // So, out_pos = (a + b + c' + d') * (a + b' + c + d') * (a + b' + c' + d)

    assign out_pos = 
        (a | b | !c | !d) &
        (a | !b | c | !d) &
        (a | !b | !c | d);

endmodule

// Truth Table/State-Transition Table for TopModule
//
// Inputs:
// clk        - positive edge-triggered clock
// areset     - asynchronous reset (active high)
// train_valid - indicates if training is active
// train_taken - indicates if the branch was taken
//
// Outputs:
// state[1:0] - 2-bit saturating counter value (0 to 3)
//
// State transitions:
// When areset is high, state is reset to 2'b01 (weakly not-taken)
// When train_valid is 1:
//   if train_taken is 1: increment counter (up to 3)
//   if train_taken is 0: decrement counter (down to 0)
// When train_valid is 0: counter remains unchanged

module TopModule (
    input  clk,
    input  areset,
    input  train_valid,
    input  train_taken,
    output reg [1:0] state
);

    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b01; // reset to weakly not-taken
        end else begin
            if (train_valid) begin
                if (train_taken) begin
                    if (state < 2'b11) begin
                        state <= state + 1;
                    end
                end else begin
                    if (state > 2'b00) begin
                        state <= state - 1;
                    end
                end
            end
        end
    end

endmodule

