module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // Derive next_state logic
    // next_state = (state == 4'b0001) ? (in ? 4'b0010 : 4'b0001) :
    //              (state == 4'b0010) ? (in ? 4'b0010 : 4'b0100) :
    //              (state == 4'b0100) ? (in ? 4'b0001 : 4'b1000) :
    //              (state == 4'b1000) ? (in ? 4'b0100 : 4'b0010) : 4'b0000;

    // Output logic: output is 1 only when in state D and in=1
    // out = (state == 4'b1000) && in;

    // Implement next_state logic
    always @(*) begin
        case (state)
            4'b0001: next_state = (in) ? 4'b0010 : 4'b0001;
            4'b0010: next_state = (in) ? 4'b0010 : 4'b0100;
            4'b0100: next_state = (in) ? 4'b0001 : 4'b1000;
            4'b1000: next_state = (in) ? 4'b0100 : 4'b0010;
            default: next_state = 4'b0000;
        endcase
    end

    // Implement output logic
    always @(*) begin
        out = 1'b0;
        if (state == 4'b1000 && in) begin
            out = 1'b1;
        end
    end

endmodule

// State Transition Table for TopModule
// State | Next state in=0, Next state in=1 | Output
// A     | A, B                             | 0
// B     | C, B                             | 0
// C     | A, D                             | 0
// D     | C, B                             | 1

module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000
    // Derive next_state and out based on state and in

    // Output logic: out is 1 only when current state is D
    assign out = (state == 4'b1000) ? 1 : 0;

    // Next state logic
    // For each state, determine next_state based on in
    // Use one-hot encoding for state and next_state

    // State A (0001)
    // in=0: next_state = A (0001)
    // in=1: next_state = B (0010)
    // State B (0010)
    // in=0: next_state = C (0100)
    // in=1: next_state = B (0010)
    // State C (0100)
    // in=0: next_state = A (0001)
    // in=1: next_state = D (1000)
    // State D (1000)
    // in=0: next_state = C (0100)
    // in=1: next_state = B (0010)

    // Using case statement for next_state
    always @(*) begin
        case (state)
            4'b0001: next_state = (in == 1'b0) ? 4'b0001 : 4'b0010; // A
            4'b0010: next_state = (in == 1'b0) ? 4'b0100 : 4'b0010; // B
            4'b0100: next_state = (in == 1'b0) ? 4'b0001 : 4'b1000; // C
            4'b1000: next_state = (in == 1'b0) ? 4'b0100 : 4'b0010; // D
            default: next_state = 4'b0000;
        endcase
    end

endmodule

module TopModule (
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output      out
);

    // State transition logic
    // State A (0001)
    // in=0 -> A, in=1 -> B
    // State B (0010)
    // in=0 -> C, in=1 -> B
    // State C (0100)
    // in=0 -> A, in=1 -> D
    // State D (1000)
    // in=0 -> C, in=1 -> B

    // next_state logic
    assign next_state = 
        (state == 4'b0001) ? 
            (in ? 4'b0010 : 4'b0001) : 
        (state == 4'b0010) ? 
            (in ? 4'b0010 : 4'b0100) : 
        (state == 4'b0100) ? 
            (in ? 4'b1000 : 4'b0001) : 
        (state == 4'b1000) ? 
            (in ? 4'b0010 : 4'b0100) : 
        4'b0000;

    // Output logic (Moore machine: output depends only on state)
    assign out = 
        (state == 4'b0001) || 
        (state == 4'b0010) || 
        (state == 4'b0100) ? 
            1'b0 : 
        1'b1;

endmodule

