    reg [255:0] next_q;

    // Internal signals for neighbor counting
    reg [255:0] neighbors;

    // Function to compute the number of live neighbors for a cell
    function [7:0] count_neighbors;
        input [7:0] row;
        input [7:0] col;
        begin
            count_neighbors = 0;
            for (int i = -1; i <= 1; i = i + 1) begin
                for (int j = -1; j <= 1; j = j + 1) begin
                    if (i == 0 && j == 0) continue;
                    int r = (row + i) % 16;
                    int c = (col + j) % 16;
                    if (current_q[(r * 16) + c]) count_neighbors = count_neighbors + 1;
                end
            end
        end
    endfunction

    // Compute neighbors for each cell
    always @(current_q) begin
        for (int i = 0; i < 16; i = i + 1) begin
            for (int j = 0; j < 16; j = j + 1) begin
                int r = i;
                int c = j;
                int neighbor_count = count_neighbors(r, c);
                if (neighbor_count == 0 || neighbor_count == 1) begin
                    next_q[(r * 16) + c] = 1'b0;
                end else if (neighbor_count == 2) begin
                    next_q[(r * 16) + c] = current_q[(r * 16) + c];
                end else if (neighbor_count == 3) begin
                    next_q[(r * 16) + c] = 1'b1;
                end else begin
                    next_q[(r * 16) + c] = 1'b0;
                end
            end
        end
    end

    // Load data into current_q on the rising edge of load
    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            current_q <= next_q;
        end
    end

    // Assign output
    assign q = current_q;

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Internal registers for next state
    reg [255:0] next_q;

    // Declare i at module level
    integer i;

    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            q <= next_q;
        end
    end

    // Compute next state based on current state (q)
    always @(*) begin
        next_q = 256'b0;
        integer j, x, y, count;
        reg [3:0] neighbors;

        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                // Calculate number of live neighbors
                count = 0;
                for (x = -1; x <= 1; x = x + 1) begin
                    for (y = -1; y <= 1; y = y + 1) begin
                        if (x == 0 && y == 0) continue;
                        integer row = (i + x + 16) % 16;
                        integer col = (j + y + 16) % 16;
                        if (q[row * 16 + col]) count = count + 1;
                    end
                end

                // Apply Conway's Game of Life rules
                if (count == 2) begin
                    next_q[i * 16 + j] = q[i * 16 + j];
                end else if (count == 3) begin
                    next_q[i * 16 + j] = 1;
                end else begin
                    next_q[i * 16 + j] = 0;
                end
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Local variables to hold the next state
    reg [255:0] next_q;

    // Function to compute the number of live neighbors for a given cell
    function [3:0] count_neighbors;
        input [255:0] current_state;
        input [4:0] row;
        input [4:0] col;
        reg [3:0] count;
        integer i, j;

        count = 4'b0000;

        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                // Calculate toroidal coordinates
                integer r = (row + i) % 16;
                integer c = (col + j) % 16;

                // Check if the neighbor is the cell itself
                if (i == 0 && j == 0) continue;

                // Check if the neighbor is alive
                if (current_state[(r * 16) + c]) count = count + 1;
            end
        end

        count_neighbors = count;
    endfunction

    // Function to compute the next state of a cell based on neighbor count
    function reg compute_next_state;
        input [3:0] neighbor_count;
        input reg current_state;

        if (neighbor_count == 4'd0 || neighbor_count == 4'd1) compute_next_state = 1'b0;
        else if (neighbor_count == 4'd2) compute_next_state = current_state;
        else if (neighbor_count == 4'd3) compute_next_state = 1'b1;
        else compute_next_state = 1'b0;
    endfunction

    // Always block to compute next state
    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            next_q = 256'b0;

            for (integer row = 0; row < 16; row = row + 1) begin
                for (integer col = 0; col < 16; col = col + 1) begin
                    integer index = (row * 16) + col;
                    reg current_state = q[index];
                    reg [3:0] neighbor_count = count_neighbors(q, row, col);
                    reg next_state = compute_next_state(neighbor_count, current_state);

                    next_q[index] = next_state;
                end
            end

            q <= next_q;
        end
    end

endmodule

