module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // Determine the current water level state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 3; // Reset to state equivalent of being above s[2]
            prev_s <= 3'b111; // All sensors asserted (above s[2])
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor input
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        state <= 3; // Above s[2]
                    end else begin
                        state <= 2; // Between s[2] and s[1]
                    end
                end else begin
                    state <= 1; // Between s[1] and s[0]
                end
            end else begin
                state <= 0; // Below s[0]
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

    // Determine outputs based on current state and previous sensor state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            case (state)
                3: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                1: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= (prev_s < s) ? 1'b1 : 1'b0;
                end
                0: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase
        end
    end

endmodule

// Truth Table/State-Transition Table for TopModule
//
// Inputs:
// clk - clock
// reset - active-high synchronous reset
// s[2:0] - 3-bit sensor input (s[2] is highest, s[0] is lowest)
//
// Outputs:
// fr2 - nominal flow rate input
// fr1 - nominal flow rate input
// fr0 - nominal flow rate input
// dfr - supplemental flow valve control (active-high)

// State: reset state (equivalent to water level below s[0])
// s[2:0] = 000 => fr2=1, fr1=1, fr0=1, dfr=0

// State: between s[2] and s[1] (s[2:0] = 011)
// fr2=0, fr1=0, fr0=1, dfr=0 (no change in level)

// State: between s[1] and s[0] (s[2:0] = 001)
// fr2=0, fr1=1, fr0=1, dfr=0 (no change in level)

// State: between s[1] and s[0] with level increased (s[2:0] = 001, previous was 011)
// fr2=0, fr1=1, fr0=1, dfr=1 (supplemental flow valve opened)

// State: below s[0] (s[2:0] = 000)
// fr2=1, fr1=1, fr0=1, dfr=0 (no change in level)

// State: above s[2] (s[2:0] = 111)
// fr2=0, fr1=0, fr0=0, dfr=0 (no change in level)

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State variables
    reg [2:0] prev_s;

    always @(posedge clk) begin
        if (reset) begin
            // Reset state: no sensors asserted, all flow inputs asserted
            fr2 <= 1;
            fr1 <= 1;
            fr0 <= 1;
            dfr <= 0;
            prev_s <= 3'b000;
        end else begin
            // Determine current water level and compare with previous
            if (s == 3'b111) begin
                // Above s[2]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
                prev_s <= s;
            end else if (s == 3'b011) begin
                // Between s[2] and s[1]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= 1'b0;
                prev_s <= s;
            end else if (s == 3'b001) begin
                // Between s[1] and s[0]
                fr2 <= 1'b0;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
                prev_s <= s;
            end else if (s == 3'b000) begin
                // Below s[0]
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
                prev_s <= s;
            end else begin
                // Default case: check if level increased
                if (s == 3'b001 && prev_s == 3'b011) begin
                    // Level increased from between s[2] and s[1] to between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b1;
                end else if (s == 3'b011 && prev_s == 3'b111) begin
                    // Level increased from above s[2] to between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b1;
                end else if (s == 3'b111 && prev_s == 3'b000) begin
                    // Level increased from below s[0] to above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b1;
                end else begin
                    // No change in level
                    fr2 <= fr2;
                    fr1 <= fr1;
                    fr0 <= fr0;
                    dfr <= dfr;
                end
                prev_s <= s;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 - below s[0], 1 - between s[1] and s[0], 2 - between s[2] and s[1], 3 - above s[2]
    reg [1:0] current_state;
    reg [1:0] previous_state;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= 2'b00; // Reset to state 0 (below s[0])
            previous_state <= 2'b00;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        current_state <= 2'b11; // Above s[2]
                    end else begin
                        current_state <= 2'b10; // Between s[2] and s[1]
                    end
                end else begin
                    current_state <= 2'b01; // Between s[1] and s[0]
                end
            end else begin
                current_state <= 2'b00; // Below s[0]
            end

            // Determine previous state based on previous sensor inputs
            previous_state <= current_state;

            // Output logic based on current state
            case (current_state)
                2'b11: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2'b10: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b01: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b00: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase

            // Check if previous level was lower than current level (sensor change)
            if (current_state > previous_state) begin
                dfr <= 1'b1;
            end
        end
    end
endmodule

